check('TC-05-C','invalid expired self blocked and authenticated invitations',function()use($u,$v,$session){$c=Ref::ensureCode($u);ok(!Ref::capture(str_repeat('f',24),$session));Ref::capture($c,$session);Ref::record($u,$session);ok(DB::table('referrals')->count()===0);$session->put(Ref::SESSION_KEY,['code'=>$c,'at'=>time()-604801]);Ref::record($v,$session);ok(DB::table('referrals')->count()===0);$u->block='yes';$u->save();ok(!Ref::capture($c,$session));$session->put(Ref::SESSION_KEY,['code'=>$c,'at'=>time()]);Ref::record($v,$session);ok(DB::table('referrals')->count()===0);$u->block='no';$u->save();Auth::login($v);$session->forget(Ref::SESSION_KEY);$r=(new App\Http\Controllers\ReferralController)->visit(req(),$c);ok($r->getStatusCode()===302);ok(!$session->has(Ref::SESSION_KEY));Auth::logout();try{(new App\Http\Controllers\ReferralController)->visit(req(),str_repeat('f',24));throw new RuntimeException('missing404');}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){ok($e->getStatusCode()===404);}});
